// Router splits addresses into the domestic (CN/HK/TW/MO) and foreign
// branches. The APNIC prefixes overlap heavily, so they are merged into
// disjoint address intervals at load time and searched by bisection.
type Router struct {
	v4 []routeInterval
	v6 []routeInterval
}

type routeInterval struct {
	first netip.Addr
	last  netip.Addr
}

// NewRouter parses and merges the embedded APNIC prefix table.
func NewRouter() *Router {
	router := &Router{}
	var v4, v6 []netip.Prefix
	for _, value := range strings.Split(domesticPrefixTable, "\n") {
		prefix, err := netip.ParsePrefix(value)
		if err != nil {
			continue
		}
		if prefix.Addr().Is4() {
			v4 = append(v4, prefix)
		} else {
			v6 = append(v6, prefix)
		}
	}
	router.v4 = mergePrefixes(v4)
	router.v6 = mergePrefixes(v6)
	return router
}

func mergePrefixes(prefixes []netip.Prefix) []routeInterval {
	ranges := make([]routeInterval, 0, len(prefixes))
	for _, prefix := range prefixes {
		last := prefix.Masked().Addr()
		// Expand the prefix to its full host range.
		ranges = append(ranges, routeInterval{first: last, last: prefixEnd(prefix)})
	}
	sort.Slice(ranges, func(i, j int) bool {
		if ranges[i].first == ranges[j].first {
			return compareAddr(ranges[i].last, ranges[j].last) < 0
		}
		return ranges[i].first.Less(ranges[j].first)
	})
	merged := make([]routeInterval, 0, len(ranges))
	for _, current := range ranges {
		if n := len(merged); n > 0 {
			previous := merged[n-1]
			if compareAddr(current.first, previous.last) <= 0 || adjacent(previous.last, current.first) {
				if compareAddr(current.last, previous.last) > 0 {
					merged[n-1] = routeInterval{first: previous.first, last: current.last}
				}
				continue
			}
		}
		merged = append(merged, current)
	}
	return merged
}

func prefixEnd(prefix netip.Prefix) netip.Addr {
	bits := prefix.Addr().BitLen()
	hostBits := bits - prefix.Bits()
	if hostBits <= 0 {
		return prefix.Addr()
	}
	if prefix.Addr().Is4() {
		raw4 := prefix.Addr().As4()
		value := binary.BigEndian.Uint32(raw4[:])
		value |= (uint32(1) << hostBits) - 1
		var raw [4]byte
		binary.BigEndian.PutUint32(raw[:], value)
		return netip.AddrFrom4(raw)
	}
	value := prefix.Addr().As16()
	for i := 15; i >= 0 && hostBits > 0; i-- {
		take := hostBits
		if take > 8 {
			take = 8
		}
		value[i] |= byte((uint16(1) << take) - 1)
		hostBits -= take
	}
	return netip.AddrFrom16(value)
}

func compareAddr(a, b netip.Addr) int {
	switch {
	case a == b:
		return 0
	case a.Less(b):
		return -1
	default:
		return 1
	}
}

func adjacent(a, b netip.Addr) bool {
	return a.Is4() == b.Is4() && nextAddr(a) == b
}

func nextAddr(a netip.Addr) netip.Addr {
	if a.Is4() {
		raw4 := a.As4()
		value := binary.BigEndian.Uint32(raw4[:])
		if value == 0xFFFFFFFF {
			return netip.Addr{}
		}
		var raw [4]byte
		binary.BigEndian.PutUint32(raw[:], value+1)
		return netip.AddrFrom4(raw)
	}
	value := a.As16()
	for i := 15; i >= 0; i-- {
		value[i]++
		if value[i] != 0 {
			break
		}
	}
	return netip.AddrFrom16(value)
}

// IsDomestic reports whether the address falls inside a CN, HK, TW, or MO
// route. Invalid addresses are foreign by default.
func (r *Router) IsDomestic(address netip.Addr) bool {
	if r == nil || !address.IsValid() {
		return false
	}
	address = address.Unmap()
	ranges := r.v4
	if address.Is6() {
		ranges = r.v6
	}
	lo, hi := 0, len(ranges)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		interval := ranges[mid]
		if interval.last.Less(address) {
			lo = mid + 1
		} else if address.Less(interval.first) {
			hi = mid - 1
		} else {
			return true
		}
	}
	return false
}
